NS_IMETHODIMP
nsMsgDBView::CellDataForColumns(int32_t aRow,
                                const nsTArray<nsString>& aColumnNames,
                                nsAString& aProperties, int32_t* aThreadLevel,
                                nsTArray<nsString>& _retval) {
  nsresult rv;
  _retval.Clear();

  rv = GetRowProperties(aRow, aProperties);
  if (NS_FAILED(rv)) {
    _retval.Clear();
    return rv;
  }
